{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.category_overall_data as WITH base_sales AS ( SELECT date, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, SUM(gross_sales::INT) AS gross_sales_value, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date >= \'2024-12-01\' GROUP BY 1,2,3 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, avg(MRP) MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' Group by 1 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) cogs from snitch_db.maplemonk.meta_mapping_cogs_sku a group by 1 ), temp as ( with a as ( select LEFT( value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING)) ) as sku_group from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ) select UPPER( sku_group ) AS sku_group_clean, from a ), as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT upper(sku_group) sku_group, sum( COALESCE(qty_available, 0) + COALESCE(qty_offline_available, 0) + COALESCE(qty_jit, 0) ) AS inv_current, sum(COALESCE(qty_available, 0)) AS online_inv_current, sum( COALESCE(qty_offline_available, 0) + COALESCE(qty_jit, 0) ) AS offline_inv_current, sum(qty_bad_inventory) bad_inv, sum(qty_blocked) blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = (select max(date) from snitch_db.maplemonk.cogs_daily_snapshot) GROUP BY 1 ), inward_lots AS ( SELECT UPPER( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS sku_group, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1, 2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT sku_group, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty, 0) - COALESCE(ic.inv_current, 0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f full outer join inv_current_by_sku ic using(sku_group) LEFT JOIN inward_total it using(sku_group) ), inv_ageing_fifo AS ( SELECT sku_group, MAX(inv_current) AS inv_current, max(online_inv_current) online_inv_current, max(offline_inv_current) offline_inv_current, max(bad_inv) bad_inv, max(blocked_inv) blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty), 0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ), inv_ageing as ( SELECT sku_group, inv_current, remaining_qty_total, weighted_age_days, online_inv_current, offline_inv_current, bad_inv, blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo ),shopify_returns AS ( SELECT sku_group, SUM(return_qty) AS total_returns_qty, SUM( CASE WHEN order_date >= CURRENT_DATE - 7 THEN return_qty ELSE 0 END ) AS l7d_returns_qty, SUM( CASE WHEN order_date >= CURRENT_DATE - 30 THEN return_qty ELSE 0 END ) AS l30d_returns_qty, SUM( CASE WHEN order_date >= DATE_TRUNC(\'month\', CURRENT_DATE) THEN return_qty ELSE 0 END ) AS mtd_returns_qty FROM snitch_db.maplemonk.return_fact_items rfi WHERE reason NOT IN (\'not_returned\') AND order_date >= \'2025-09-01\' GROUP BY 1 ), clicks_data AS ( SELECT sku_group, SUM(clicks) AS overall_clicks, SUM( CASE WHEN ga_date::DATE >= CURRENT_DATE - 7 THEN clicks ELSE 0 END ) AS l7d_clicks, SUM( CASE WHEN ga_date::DATE >= CURRENT_DATE - 30 THEN clicks ELSE 0 END ) AS l30d_clicks, SUM( CASE WHEN ga_date::DATE >= DATE_TRUNC(\'month\', CURRENT_DATE) THEN clicks ELSE 0 END ) AS mtd_clicks FROM snitch_db.maplemonk.clicks_itemid c WHERE ga_date::DATE >= \'2026-04-01\' GROUP BY 1 ), returns_overall AS ( WITH a AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS sku_group, \"PUTAWAY_UPDATED\"::DATE AS date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= \'2025-06-01\' AND \"PUTAWAY_UPDATED\"::DATE < \'2026-12-01\' AND LOWER(FINAL_TYPE) LIKE \'b2c return%\' GROUP BY 1,2 ) SELECT sku_group, SUM(qty) AS overall_returns_qty, SUM( CASE WHEN date >= CURRENT_DATE - 7 THEN qty ELSE 0 END ) AS l7d_returns_qty, SUM( CASE WHEN date >= CURRENT_DATE - 30 THEN qty ELSE 0 END ) AS l30d_returns_qty, SUM( CASE WHEN date >= DATE_TRUNC(\'month\', CURRENT_DATE) THEN qty ELSE 0 END ) AS mtd_returns_qty FROM a GROUP BY 1 ),inwards_data AS ( WITH a AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS sku_group, \"PUTAWAY_UPDATED\"::DATE AS date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= \'2026-04-01\' AND \"PUTAWAY_UPDATED\"::DATE < \'2027-12-01\' AND LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2 ) SELECT sku_group, SUM(qty) AS overall_inward_qty, SUM( CASE WHEN date >= CURRENT_DATE - 7 THEN qty ELSE 0 END ) AS l7d_inward_qty, SUM( CASE WHEN date >= CURRENT_DATE - 30 THEN qty ELSE 0 END ) AS l30d_inward_qty, SUM( CASE WHEN date >= DATE_TRUNC(\'month\', CURRENT_DATE) THEN qty ELSE 0 END ) AS mtd_inward_qty FROM a GROUP BY 1 ) SELECT sku_group, mm.l1_category AS l1_category, mm.category AS category, mm.meta1 AS meta1, mm.meta2 AS meta2, mm.meta3 AS meta3, fs.total_remark FS_remarks_overall, fs.total_online_remark FS_remarks_online, fs.wh_remark FS_Remarks_Offline_WH, MAX(mm.cogs) AS cogs, MAX( CASE WHEN sku_group IN ( SELECT sku_group_clean FROM temp ) THEN \'Catalogued\' ELSE \'Not Catalogued\' END ) AS catalogued, MAX(COALESCE(ia.inv_current, 0)) AS inv_current, MAX(COALESCE(ia.online_inv_current, 0)) AS online_inv_current, MAX(COALESCE(ia.offline_inv_current, 0)) AS offline_inv_current, MAX(COALESCE(ia.bad_inv, 0)) AS bad_inv, MAX(COALESCE(ia.blocked_inv, 0)) AS blocked_inv, MAX(COALESCE(ia.inventory_ageing_bucket, \'0-30\')) AS inv_ageing, MAX(COALESCE(ia.inv_current, 0)) * MAX(COALESCE(mm.cogs, 0)) AS cogs_overall_inventory_current, MAX(COALESCE(ia.online_inv_current, 0)) * MAX(COALESCE(mm.cogs, 0)) AS cogs_online_inv_current, MAX(COALESCE(ia.offline_inv_current, 0)) * MAX(COALESCE(mm.cogs, 0)) AS cogs_offline_inv_current, MAX(COALESCE(ia.bad_inv, 0)) * MAX(COALESCE(mm.cogs, 0)) AS cogs_bad_inv, MAX(COALESCE(ia.blocked_inv, 0)) * MAX(COALESCE(mm.cogs, 0)) AS cogs_blocked_inv, SUM( CASE WHEN bs.date >= CURRENT_DATE - 7 THEN bs.gross_sales_value ELSE 0 END ) AS overall_l7d_gross_sales, SUM( CASE WHEN bs.date >= CURRENT_DATE - 15 THEN bs.gross_sales_value ELSE 0 END ) AS overall_l15d_gross_sales, SUM( CASE WHEN bs.date >= CURRENT_DATE - 30 THEN bs.gross_sales_value ELSE 0 END ) AS overall_l30d_gross_sales, SUM( CASE WHEN bs.date >= CURRENT_DATE - 60 THEN bs.gross_sales_value ELSE 0 END ) AS overall_l60d_gross_sales, SUM( CASE WHEN bs.date >= CURRENT_DATE - 90 THEN bs.gross_sales_value ELSE 0 END ) AS overall_l90d_gross_sales, SUM( CASE WHEN bs.date >= CURRENT_DATE - 7 THEN bs.qty ELSE 0 END ) AS overall_l7d_qty, SUM( CASE WHEN bs.date >= CURRENT_DATE - 15 THEN bs.qty ELSE 0 END ) AS overall_l15d_qty, SUM( CASE WHEN bs.date >= CURRENT_DATE - 30 THEN bs.qty ELSE 0 END ) AS overall_l30d_qty, SUM( CASE WHEN bs.date >= CURRENT_DATE - 60 THEN bs.qty ELSE 0 END ) AS overall_l60d_qty, SUM( CASE WHEN bs.date >= CURRENT_DATE - 90 THEN bs.qty ELSE 0 END ) AS overall_l90d_qty, SUM( CASE WHEN bs.date >= CURRENT_DATE - 7 THEN bs.qty * COALESCE(mrp.MRP, 0) ELSE 0 END ) AS overall_l7d_mrp_value, SUM( CASE WHEN bs.date >= CURRENT_DATE - 15 THEN bs.qty * COALESCE(mrp.MRP, 0) ELSE 0 END ) AS overall_l15d_mrp_value, SUM( CASE WHEN bs.date >= CURRENT_DATE - 30 THEN bs.qty * COALESCE(mrp.MRP, 0) ELSE 0 END ) AS overall_l30d_mrp_value, SUM( CASE WHEN bs.date >= CURRENT_DATE - 60 THEN bs.qty * COALESCE(mrp.MRP, 0) ELSE 0 END ) AS overall_l60d_mrp_value, SUM( CASE WHEN bs.date >= CURRENT_DATE - 90 THEN bs.qty * COALESCE(mrp.MRP, 0) ELSE 0 END ) AS overall_l90d_mrp_value, SUM( CASE WHEN bs.date >= CURRENT_DATE - 7 THEN (bs.qty * COALESCE(mrp.MRP, 0)) - bs.gross_sales_value ELSE 0 END ) AS overall